<!DOCTYPE html>
<html>
<head>
  <title>Personal Expense Tracker</title>
  <style>
    body { font-family: sans-serif; }
    #container { display: flex; }
    #form { width: 30%; padding: 20px; margin-right: 20px; border: 1px solid #ccc; }
    #list { width: 70%; padding: 20px; border: 1px solid #ccc; }
    .expense { display: flex; align-items: baseline; }
    .exp-del { cursor: pointer; margin-left: 10px; font-weight: bold; }
    .cat-total { display: block; margin-bottom: 5px; }
  </style>
</head>
<body>

  <h1>Personal Expense Tracker</h1>

  <div id="container">
    <div id="form">
      <label for="amount">Amount:</label>
      <input type="number" id="amount"><br><br>

      <label for="category">Category:</label>
      <select id="category">
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
      </select><br><br>

      <label for="date">Date:</label>
      <input type="date" id="date"><br><br>

      <label for="note">Note (optional):</label>
      <textarea id="note"></textarea><br><br>

      <button id="add-expense">Add Expense</button>
      <p id="form-error"></p>
    </div>

    <div id="list">
      <h2>Expenses</h2>
      <ul class="expenses"></ul>
      <ul>
        <li>Total: <span id="total">0.00</span></li>
      </ul>

      <h3>Category Totals</h3>
      <div class="cat-total" data-cat="groceries"></div>
      <div class="cat-total" data-cat="transport"></div>
      <div class="cat-total" data-cat="bills"></div>
      <div class="cat-total" data-cat="fun"></div>

      <label for="filter-category">Filter Category:</label>
      <select id="filter-category">
        <option value="all">All</option>
      </select><br>

      <label for="filter-from">From Date:</label>
      <input type="date" id="filter-from"><br>

      <label for="filter-to">To Date:</label>
      <input type="date" id="filter-to"><br>
    </div>
  </div>


  <script>
    const expensesList = document.querySelector('.expenses');
    const totalSpan = document.getElementById('total');
    const formError = document.getElementById('form-error');
    const amountInput = document.getElementById('amount');
    const categorySelect = document.getElementById('category');
    const dateInput = document.getElementById('date');
    const noteTextarea = document.getElementById('note');
    const addExpenseButton = document.getElementById('add-expense');
    const filterCategorySelect = document.getElementById('filter-category');
    const filterFromDateInput = document.getElementById('filter-from');
    const filterToDateInput = document.getElementById('filter-to');

    let visibleExpenses = [];

    function loadExpenses() {
      const storedExpenses = localStorage.getItem('expenses') || '[]';
      visibleExpenses = JSON.parse(storedExpenses);
      renderExpenses();
      renderCategoryTotals();
      updateTotal();
    }

    function renderExpenses() {
      expensesList.innerHTML = '';
      visibleExpenses.forEach((expense, index) => {
        const li = document.createElement('li');
        li.classList.add('expense');
        li.innerHTML = `
          ${expense.amount}: ${expense.category} (${expense.date}) 
          <button class="exp-del" data-id="${index}">Delete</button>
        `;
        expensesList.appendChild(li);
      });
    }

    function renderCategoryTotals() {
      const categoryTotalsContainer = document.querySelectorAll('.cat-total');
      categoryTotalsContainer.forEach(catTotal => {
        const catValue = catTotal.getAttribute('data-cat');
        let total = 0;
        visibleExpenses.forEach(expense => {
          if (expense.category === catValue) {
            total += expense.amount;
          }
        });
        catTotal.textContent = `${total.toFixed(2)}`;
      });
    }

    function updateTotal() {
      let total = 0;
      visibleExpenses.forEach(expense => {
        total += expense.amount;
      });
      totalSpan.textContent = total.toFixed(2);
    }


    function addExpense(event) {
      event.preventDefault();
      const amount = parseFloat(amountInput.value);
      const category = categorySelect.value;
      const date = dateInput.value;
      const note = noteTextarea.value || '';

      if (isNaN(amount) || amount <= 0 || !date) {
        formError.textContent = 'Please enter a valid amount and date.';
        return;
      }

      const newExpense = { amount, category, date, note };
      visibleExpenses.push(newExpense);
      renderExpenses();
      updateTotal();
      localStorage.setItem('expenses', JSON.stringify(visibleExpenses));
      formError.textContent = '';
      amountInput.value = '';
    }

    function deleteExpense(event) {
        const id = event.target.dataset.id;
        visibleExpenses.splice(id, 1);
        renderExpenses();
        updateTotal();
        localStorage.setItem('expenses', JSON.stringify(visibleExpenses));
    }


    loadExpenses();
    addExpenseButton.addEventListener('click', addExpense);
    expensesList.addEventListener('click', (event) => {
      if (event.target.classList.contains('exp-del')) {
        deleteExpense(event);
      }
    });

    filterCategorySelect.addEventListener('change', () => {
      const selectedCategory = filterCategorySelect.value;
      visibleExpenses = visibleExpenses.filter(expense => selectedCategory === 'all' || expense.category === selectedCategory);
      renderExpenses();
      renderCategoryTotals();
      updateTotal();
    });

    filterFromDateInput.addEventListener('change', () => {
      const fromDate = filterFromDateInput.value;
      const toDate = filterToDateInput.value;

      visibleExpenses = visibleExpenses.filter(expense => {
        const expenseDate = new Date(expense.date);
        const fromDateObj = fromDate ? new Date(fromDate) : new Date('1900-01-01'); //Default to beginning of time if empty
        const toDateObj = toDate ? new Date(toDate) : new Date('2100-01-01');  //Default to end of time if empty

        return expenseDate >= fromDateObj && expenseDate <= toDateObj;
      });
      renderExpenses();
      renderCategoryTotals();
      updateTotal();
    });
  </script>

</body>
</html>
